-- SUNNY FLEX 3D: thiết kế cơ sở dữ liệu mục tiêu (SQLite 3.35+), KHÔNG phải migration đã triển khai vào server cũ.
PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS organizations(id TEXT PRIMARY KEY,name TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS departments(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organizations(id),name TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS permissions(code TEXT PRIMARY KEY,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id TEXT REFERENCES roles(id),permission_code TEXT REFERENCES permissions(code),PRIMARY KEY(role_id,permission_code));
CREATE TABLE IF NOT EXISTS employees(id TEXT PRIMARY KEY,department_id TEXT REFERENCES departments(id),employee_code TEXT NOT NULL UNIQUE,full_name TEXT NOT NULL,position TEXT,status TEXT NOT NULL DEFAULT 'active',hired_on TEXT,source_kind TEXT NOT NULL DEFAULT 'manual',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS employee_private(employee_id TEXT PRIMARY KEY REFERENCES employees(id),encrypted_payload BLOB NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS app_users(id TEXT PRIMARY KEY,employee_id TEXT REFERENCES employees(id),username TEXT NOT NULL UNIQUE,password_hash TEXT NOT NULL,is_active INTEGER NOT NULL DEFAULT 1 CHECK(is_active IN (0,1)));
CREATE TABLE IF NOT EXISTS user_roles(user_id TEXT REFERENCES app_users(id),role_id TEXT REFERENCES roles(id),PRIMARY KEY(user_id,role_id));
CREATE TABLE IF NOT EXISTS duty_catalog(id TEXT PRIMARY KEY,position TEXT NOT NULL,title TEXT NOT NULL,frequency TEXT NOT NULL,expected_evidence TEXT,weight REAL NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS duty_assignments(id TEXT PRIMARY KEY,employee_id TEXT REFERENCES employees(id),duty_id TEXT REFERENCES duty_catalog(id),start_on TEXT NOT NULL,end_on TEXT);
CREATE TABLE IF NOT EXISTS audit_log(id INTEGER PRIMARY KEY AUTOINCREMENT,actor_id TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,at TEXT NOT NULL,request_id TEXT,old_json TEXT,new_json TEXT);
CREATE TABLE IF NOT EXISTS documents(id TEXT PRIMARY KEY,sha256 TEXT NOT NULL,original_name TEXT,media_type TEXT,storage_path TEXT NOT NULL,received_at TEXT NOT NULL,uploaded_by TEXT,source_kind TEXT NOT NULL CHECK(source_kind IN ('real','sample','imported')),ocr_status TEXT NOT NULL DEFAULT 'pending',UNIQUE(sha256,source_kind));
CREATE TABLE IF NOT EXISTS extraction_results(id TEXT PRIMARY KEY,document_id TEXT NOT NULL REFERENCES documents(id),document_type TEXT NOT NULL,fields_json TEXT NOT NULL,confidence REAL CHECK(confidence BETWEEN 0 AND 1),model_name TEXT,review_status TEXT NOT NULL DEFAULT 'pending',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS suppliers(id TEXT PRIMARY KEY,name TEXT NOT NULL,tax_code TEXT,phone TEXT,address TEXT);
CREATE TABLE IF NOT EXISTS customers(id TEXT PRIMARY KEY,customer_code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,phone TEXT,province TEXT,owner_employee_id TEXT REFERENCES employees(id),source_kind TEXT NOT NULL DEFAULT 'real',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS customer_interactions(id TEXT PRIMARY KEY,customer_id TEXT REFERENCES customers(id),employee_id TEXT REFERENCES employees(id),channel TEXT,occurred_at TEXT NOT NULL,outcome TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS marketing_campaigns(id TEXT PRIMARY KEY,name TEXT NOT NULL,channel TEXT,budget_amount INTEGER NOT NULL DEFAULT 0 CHECK(budget_amount>=0),owner_employee_id TEXT REFERENCES employees(id),starts_on TEXT,ends_on TEXT,status TEXT NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS marketing_leads(id TEXT PRIMARY KEY,campaign_id TEXT REFERENCES marketing_campaigns(id),customer_id TEXT REFERENCES customers(id),created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'new');
CREATE TABLE IF NOT EXISTS sales_orders(id TEXT PRIMARY KEY,order_code TEXT NOT NULL UNIQUE,customer_id TEXT NOT NULL REFERENCES customers(id),campaign_id TEXT REFERENCES marketing_campaigns(id),owner_employee_id TEXT REFERENCES employees(id),ordered_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'draft',source_kind TEXT NOT NULL DEFAULT 'real');
CREATE TABLE IF NOT EXISTS products(id TEXT PRIMARY KEY,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,unit TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS order_lines(id TEXT PRIMARY KEY,order_id TEXT NOT NULL REFERENCES sales_orders(id),product_id TEXT NOT NULL REFERENCES products(id),quantity REAL NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),discount INTEGER NOT NULL DEFAULT 0 CHECK(discount>=0));
CREATE TABLE IF NOT EXISTS receipts(id TEXT PRIMARY KEY,order_id TEXT REFERENCES sales_orders(id),received_at TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>0),reference TEXT UNIQUE,verified INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS inventory_items(id TEXT PRIMARY KEY,sku TEXT NOT NULL UNIQUE,name TEXT NOT NULL,category TEXT NOT NULL CHECK(category IN ('production','spares','office','tools','finished','other')),unit TEXT NOT NULL,standard_qty REAL NOT NULL DEFAULT 0,lead_days REAL NOT NULL DEFAULT 0,daily_usage REAL NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS warehouses(id TEXT PRIMARY KEY,name TEXT NOT NULL,location TEXT);
CREATE TABLE IF NOT EXISTS stock_lots(id TEXT PRIMARY KEY,item_id TEXT NOT NULL REFERENCES inventory_items(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),supplier_id TEXT REFERENCES suppliers(id),received_at TEXT NOT NULL,unit_cost INTEGER NOT NULL DEFAULT 0,source_document_id TEXT REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS stock_movements(id TEXT PRIMARY KEY,request_id TEXT NOT NULL UNIQUE,item_id TEXT NOT NULL REFERENCES inventory_items(id),lot_id TEXT REFERENCES stock_lots(id),warehouse_id TEXT NOT NULL REFERENCES warehouses(id),batch_id TEXT,kind TEXT NOT NULL CHECK(kind IN ('in','out','adjust','transfer')),quantity_delta REAL NOT NULL CHECK(quantity_delta!=0),occurred_at TEXT NOT NULL,actor_id TEXT,source_document_id TEXT REFERENCES documents(id),source_kind TEXT NOT NULL DEFAULT 'real');
CREATE INDEX IF NOT EXISTS idx_stock_movements_item_time ON stock_movements(item_id,occurred_at);
CREATE VIEW IF NOT EXISTS inventory_balances AS SELECT item_id,warehouse_id,SUM(quantity_delta) AS on_hand FROM stock_movements GROUP BY item_id,warehouse_id;
CREATE TABLE IF NOT EXISTS asset_categories(id TEXT PRIMARY KEY,name TEXT NOT NULL,accounting_class TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS assets(id TEXT PRIMARY KEY,asset_code TEXT NOT NULL UNIQUE,name TEXT NOT NULL,category_id TEXT REFERENCES asset_categories(id),acquired_on TEXT,acquisition_cost INTEGER NOT NULL DEFAULT 0 CHECK(acquisition_cost>=0),residual_value INTEGER NOT NULL DEFAULT 0 CHECK(residual_value>=0),custodian_id TEXT REFERENCES employees(id),location TEXT,status TEXT NOT NULL DEFAULT 'in_use',source_document_id TEXT REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS asset_events(id TEXT PRIMARY KEY,asset_id TEXT NOT NULL REFERENCES assets(id),event_type TEXT NOT NULL,occurred_at TEXT NOT NULL,from_employee_id TEXT,to_employee_id TEXT,amount INTEGER NOT NULL DEFAULT 0,notes TEXT);
CREATE TABLE IF NOT EXISTS purchases(id TEXT PRIMARY KEY,invoice_no TEXT,supplier_id TEXT REFERENCES suppliers(id),purchased_on TEXT NOT NULL,total_amount INTEGER NOT NULL CHECK(total_amount>=0),classification TEXT NOT NULL CHECK(classification IN ('inventory','asset','prepaid','expense','pending')),document_id TEXT REFERENCES documents(id),request_id TEXT NOT NULL UNIQUE,source_kind TEXT NOT NULL DEFAULT 'real');
CREATE TABLE IF NOT EXISTS purchase_lines(id TEXT PRIMARY KEY,purchase_id TEXT NOT NULL REFERENCES purchases(id),description TEXT NOT NULL,quantity REAL NOT NULL CHECK(quantity>0),unit_price INTEGER NOT NULL CHECK(unit_price>=0),tax_amount INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS production_batches(id TEXT PRIMARY KEY,batch_code TEXT NOT NULL UNIQUE,product_id TEXT REFERENCES products(id),shift_date TEXT NOT NULL,shift_code TEXT,leader_id TEXT REFERENCES employees(id),output_gross REAL NOT NULL DEFAULT 0,output_pass REAL NOT NULL DEFAULT 0,output_reject REAL NOT NULL DEFAULT 0,source_kind TEXT NOT NULL DEFAULT 'real',CHECK(output_gross>=0 AND output_pass>=0 AND output_reject>=0));
CREATE TABLE IF NOT EXISTS batch_workers(batch_id TEXT REFERENCES production_batches(id),employee_id TEXT REFERENCES employees(id),is_leader INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(batch_id,employee_id));
CREATE TABLE IF NOT EXISTS qc_inspections(id TEXT PRIMARY KEY,batch_id TEXT NOT NULL REFERENCES production_batches(id),inspected_at TEXT NOT NULL,inspector_id TEXT REFERENCES employees(id),test_type TEXT NOT NULL,result TEXT NOT NULL,evidence_document_id TEXT REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS meters(id TEXT PRIMARY KEY,name TEXT NOT NULL,zone TEXT,unit TEXT NOT NULL DEFAULT 'kWh',source_kind TEXT NOT NULL DEFAULT 'manual');
CREATE TABLE IF NOT EXISTS meter_readings(id TEXT PRIMARY KEY,meter_id TEXT NOT NULL REFERENCES meters(id),read_at TEXT NOT NULL,reading REAL NOT NULL CHECK(reading>=0),source_document_id TEXT REFERENCES documents(id),UNIQUE(meter_id,read_at));
CREATE TABLE IF NOT EXISTS energy_allocations(id TEXT PRIMARY KEY,meter_id TEXT REFERENCES meters(id),batch_id TEXT REFERENCES production_batches(id),period_start TEXT NOT NULL,period_end TEXT NOT NULL,kwh REAL NOT NULL CHECK(kwh>=0),cost_amount INTEGER NOT NULL CHECK(cost_amount>=0));
CREATE TABLE IF NOT EXISTS attendance(id TEXT PRIMARY KEY,employee_id TEXT NOT NULL REFERENCES employees(id),work_date TEXT NOT NULL,shift_code TEXT,hours REAL NOT NULL DEFAULT 0 CHECK(hours BETWEEN 0 AND 24),source_kind TEXT NOT NULL DEFAULT 'real',UNIQUE(employee_id,work_date,shift_code));
CREATE TABLE IF NOT EXISTS payroll_drafts(id TEXT PRIMARY KEY,employee_id TEXT NOT NULL REFERENCES employees(id),period TEXT NOT NULL,base_salary INTEGER NOT NULL DEFAULT 0,kpi_bonus INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft',UNIQUE(employee_id,period));
CREATE TABLE IF NOT EXISTS kpi_definitions(id TEXT PRIMARY KEY,code TEXT UNIQUE NOT NULL,title TEXT NOT NULL,role_id TEXT REFERENCES roles(id),unit TEXT NOT NULL,aggregation TEXT NOT NULL,weight REAL NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS kpi_measurements(id TEXT PRIMARY KEY,kpi_id TEXT NOT NULL REFERENCES kpi_definitions(id),employee_id TEXT REFERENCES employees(id),period_type TEXT NOT NULL CHECK(period_type IN ('day','week','month','quarter','year')),period_start TEXT NOT NULL,target REAL NOT NULL,actual REAL,verified INTEGER NOT NULL DEFAULT 0,source_kind TEXT NOT NULL DEFAULT 'real',UNIQUE(kpi_id,employee_id,period_type,period_start));
CREATE TABLE IF NOT EXISTS incidents(id TEXT PRIMARY KEY,incident_code TEXT UNIQUE NOT NULL,category TEXT NOT NULL,occurred_at TEXT NOT NULL,department_id TEXT REFERENCES departments(id),employee_id TEXT REFERENCES employees(id),batch_id TEXT REFERENCES production_batches(id),estimated_loss INTEGER NOT NULL DEFAULT 0,verified_loss INTEGER,status TEXT NOT NULL DEFAULT 'open',evidence_document_id TEXT REFERENCES documents(id));
CREATE TABLE IF NOT EXISTS cost_transactions(id TEXT PRIMARY KEY,source_type TEXT NOT NULL,source_id TEXT NOT NULL,category TEXT NOT NULL,occurred_on TEXT NOT NULL,amount INTEGER NOT NULL CHECK(amount>=0),period TEXT NOT NULL,source_kind TEXT NOT NULL DEFAULT 'real',UNIQUE(source_type,source_id,category));
CREATE TABLE IF NOT EXISTS cost_opportunities(id TEXT PRIMARY KEY,category TEXT NOT NULL,root_cause TEXT,evidence_json TEXT,estimated_saving INTEGER NOT NULL DEFAULT 0,verified_saving INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'suspected',owner_id TEXT REFERENCES employees(id),created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS agent_definitions(id TEXT PRIMARY KEY,name TEXT NOT NULL,scope TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS agent_runs(id TEXT PRIMARY KEY,agent_id TEXT NOT NULL REFERENCES agent_definitions(id),trigger_type TEXT NOT NULL,started_at TEXT NOT NULL,finished_at TEXT,status TEXT NOT NULL,input_digest TEXT,output_json TEXT,error_code TEXT);
CREATE TABLE IF NOT EXISTS alerts(id TEXT PRIMARY KEY,source_type TEXT NOT NULL,source_id TEXT NOT NULL,severity TEXT NOT NULL,threshold REAL,observed REAL,created_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'open',UNIQUE(source_type,source_id,severity,status));
CREATE TABLE IF NOT EXISTS approvals(id TEXT PRIMARY KEY,entity_type TEXT NOT NULL,entity_id TEXT NOT NULL,action TEXT NOT NULL,requested_by TEXT,approved_by TEXT,decision TEXT NOT NULL DEFAULT 'pending',decided_at TEXT,notes TEXT);
CREATE TABLE IF NOT EXISTS sync_inbox(id TEXT PRIMARY KEY,source_system TEXT NOT NULL,external_id TEXT NOT NULL,payload_json TEXT NOT NULL,received_at TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'pending',UNIQUE(source_system,external_id));
CREATE TABLE IF NOT EXISTS backups(id TEXT PRIMARY KEY,path TEXT NOT NULL,created_at TEXT NOT NULL,sha256 TEXT NOT NULL,verified INTEGER NOT NULL DEFAULT 0);
